import 'dart:convert';
import 'dart:typed_data';

const Map<int, String> weeklyRewardImageBase64 = <int, String>{
  1: '',
  2: '',
  3: '',
  4: '',
  5: '',
  6: '',
  7: '',
};

Uint8List weeklyRewardImageBytes(int day) =>
    base64Decode(weeklyRewardImageBase64[day] ?? weeklyRewardImageBase64[1]!);